        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): FfiVaultSession {
        return FfiVaultSession(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): FfiVaultSession {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: FfiVaultSession) = 8UL

    override fun write(value: FfiVaultSession, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}





/**
 * A flat, payload-free FFI error.
 *
 * The variant names mirror [`ErrorCode`] one-to-one. Kotlin maps them to the
 * stable numeric codes in `ErrorMapping.kt`; the Rust table test keeps both
 * sides honest.
 */
sealed class FfiException: kotlin.Exception() {
    
    /**
     * Caller input was malformed or outside an allowed range.
     */
    class InvalidArgument(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * A format or schema version is newer than this build supports.
     */
    class UnsupportedVersion(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The vault could not be opened. Deliberately generic.
     */
    class AuthenticationFailed(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Data is malformed or fails an integrity check.
     */
    class CorruptData(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The operation requires an unlocked vault.
     */
    class Locked(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The requested record does not exist.
     */
    class NotFound(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * A concurrent change requires resolution.
     */
    class Conflict(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * A resource limit was exceeded.
     */
    class LimitExceeded(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Platform storage failed.
     */
    class Storage(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Internal invariant failure.
     */
    class Internal(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Parameters fail the security policy.
     */
    class PolicyRejected(
        ) : FfiException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.InvalidArgument()
            2 -> FfiException.UnsupportedVersion()
            3 -> FfiException.AuthenticationFailed()
            4 -> FfiException.CorruptData()
            5 -> FfiException.Locked()
            6 -> FfiException.NotFound()
            7 -> FfiException.Conflict()
            8 -> FfiException.LimitExceeded()
            9 -> FfiException.Storage()
            10 -> FfiException.Internal()
            11 -> FfiException.PolicyRejected()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.UnsupportedVersion -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.AuthenticationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.CorruptData -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Locked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Conflict -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.LimitExceeded -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.PolicyRejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.InvalidArgument -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.UnsupportedVersion -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.AuthenticationFailed -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.CorruptData -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.Locked -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.NotFound -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.Conflict -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.LimitExceeded -> {
                buf.putInt(8)
                Unit
            }
            is FfiException.Storage -> {
                buf.putInt(9)
                Unit
            }
            is FfiException.Internal -> {
                buf.putInt(10)
                Unit
            }
            is FfiException.PolicyRejected -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterSequenceString: FfiConverterRustBuffer<List<kotlin.String>> {
    override fun read(buf: ByteBuffer): List<kotlin.String> {
        val len = buf.getInt()
        return List<kotlin.String>(len) {
            FfiConverterString.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.String>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterString.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterString.write(it, buf)
        }
    }
}




